// === Tab: mySketch ===
/**
 * NEURO_GARDEN // SYNAPTIC_BLOOM
 * Trend: Algorithmic Botany & Evolutionary Art.
 * * CONCEPT:
 * A digital ecosystem that grows, branches, and blooms based on user proximity.
 * It visualizes the bridge between biological growth patterns and neural networks.
 * * CONTROLS:
 * - MOUSE MOVE: Act as the "Sun" (Energy Source). The roots grow towards you.
 * - CLICK: Plant a new "Seed" (Explosion of life).
 */

let agents = [];
let maxAgents = 1000; // Limite pour garantir 60FPS constant
let colorOffset = 0;

function setup() {
  createCanvas(windowWidth, windowHeight);
  background(0); // Noir pur
  colorMode(HSB, 360, 100, 100, 100);
  noSmooth();

  // On commence avec une explosion centrale
  spawnSeed(width/2, height/2);
}

function draw() {
  // Pas de background() complet pour garder les traces (Peinture cumulative)
  // On assombrit très légèrement pour donner de la profondeur (Depth fade)
  noStroke();
  fill(0, 0, 0, 1); // Opacité ultra-faible (1%)
  rect(0, 0, width, height);

  // Évolution de la palette globale
  colorOffset += 0.5;

  // Mise à jour des agents (racines)
  blendMode(ADD); // Mode lumière pour l'effet Néon/Bioluminescent

  for (let i = agents.length - 1; i >= 0; i--) {
    let a = agents[i];
    a.update();
    a.display();

    // Si l'agent meurt (plus d'énergie), on le supprime
    if (a.isDead()) {
      agents.splice(i, 1);
    } 
    // Reproduction : Si l'agent est en pleine forme, il se divise (Branching)
    else if (a.life > 50 && random() < 0.02 && agents.length < maxAgents) {
      agents.push(a.branch());
    }
  }

  blendMode(BLEND); // Retour normal pour l'UI
  drawUI();
}

function spawnSeed(x, y) {
  // Création de 50 agents d'un coup en cercle
  for (let i = 0; i < 50; i++) {
    let angle = random(TWO_PI);
    let vel = p5.Vector.fromAngle(angle);
    agents.push(new RootAgent(x, y, vel));
  }
}

class RootAgent {
  constructor(x, y, vel) {
    this.pos = createVector(x, y);
    this.vel = vel.copy();
    this.acc = createVector(0, 0);
    this.life = 255; // Durée de vie
    this.maxSpeed = 2;
    this.maxForce = 0.1;
    // Couleur unique basée sur le temps global + variation locale
    this.hue = (colorOffset + random(50)) % 360;
  }

  update() {
    // 1. COMPORTEMENT (Seeker)
    // L'agent est attiré par la souris (Lumière)
    let mouse = createVector((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
    let dir = p5.Vector.sub(mouse, this.pos);

    // Si on est proche de la souris, l'attraction est forte
    let d = dir.mag();
    if (d < 400) {
      dir.setMag(0.1); // Force d'attraction douce
      this.applyForce(dir);
    }

    // 2. MOUVEMENT ORGANIQUE (Perlin Noise)
    // Ajoute du chaos naturel pour ne pas avoir des lignes droites
    let noiseAngle = noise(this.pos.x * 0.01, this.pos.y * 0.01, frameCount * 0.01) * TWO_PI * 4;
    let noiseForce = p5.Vector.fromAngle(noiseAngle);
    noiseForce.mult(0.2); // Force du vent/chaos
    this.applyForce(noiseForce);

    // Physique
    this.vel.add(this.acc);
    this.vel.limit(this.maxSpeed);
    this.pos.add(this.vel);
    this.acc.mult(0);

    // Vieillissement
    this.life -= 1.5;
  }

  applyForce(force) {
    this.acc.add(force);
  }

  branch() {
    // Crée une nouvelle racine qui part légèrement de côté
    let newVel = this.vel.copy().rotate(random(-0.5, 0.5));
    let child = new RootAgent(this.pos.x, this.pos.y, newVel);
    child.life = this.life; // Hérite de la vie restante
    return child;
  }

  isDead() {
    return this.life <= 0 || 
           this.pos.x < 0 || this.pos.x > width || 
           this.pos.y < 0 || this.pos.y > height;
  }

  display() {
    // La couleur change avec l'âge (plus blanc au début, plus coloré à la fin)
    // L'épaisseur diminue avec l'âge
    let w = map(this.life, 0, 255, 0, 3);
    let alpha = map(this.life, 0, 255, 0, 100);

    strokeWeight(w);
    stroke(this.hue, 80, 100, alpha);

    // On dessine un point (ou une petite ligne)
    point(this.pos.x, this.pos.y);
  }
}

function drawUI() {
  fill(255);
  noStroke();
  textFont('Courier New');
  textSize(12);
  textAlign(LEFT, TOP);

  text("NEURO_GARDEN // V.4.0", 20, 20);
  text("ACTIVE_AGENTS: " + agents.length, 20, 35);
  text("ECOSYSTEM_AGE: " + floor(frameCount / 60) + "s", 20, 50);
}

function mousePressed() {
  spawnSeed((window.simulatedMouseX !== undefined ? window.simulatedMouseX : (typeof sub_bass !== 'undefined' ? map(sub_bass, 0, 1, width*0.1, width*0.9) : (typeof live_centroid !== 'undefined' ? map(live_centroid, 100, 4000, 0, width) : mouseX))), (window.simulatedMouseY !== undefined ? window.simulatedMouseY : (typeof percussive !== 'undefined' ? map(percussive, 0, 1, height, 0) : (typeof roughness !== 'undefined' ? map(roughness, 0, 1, height*0.2, height*0.8) : mouseY))));
}

function windowResized() {
  resizeCanvas(windowWidth, windowHeight);
  background(0);
}

